import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句","description":"L1–L20 规则、例句、易错点。","frontmatter":{"title":"第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句","description":"L1–L20 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-3/unit-01/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 1 语法总结","summary":"L1–L20 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 1 语法总结","link":"/life/english/new-concept/book-3/unit-01/grammar"},"next":{"text":"第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果","link":"/life/english/new-concept/book-3/unit-01/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 1 语法总结","link":"/life/english/new-concept/book-3/unit-01/grammar"},"next":{"text":"第三册：培养技能 · 单元 1 语法总结 · 转述要求与否定命令至过去将来时与计划结果","link":"/life/english/new-concept/book-3/unit-01/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/grammar-part-01.md","filePath":"life/english/new-concept/book-3/unit-01/grammar-part-01.md"}'),r={name:"life/english/new-concept/book-3/unit-01/grammar-part-01.md"};function s(i,e,h,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-单元-1-语法总结-·-定语从句与证据限定至过去反事实条件句" tabindex="-1">第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-语法总结-·-定语从句与证据限定至过去反事实条件句" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1 语法总结 · 定语从句与证据限定至过去反事实条件句&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-01/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><h2 id="第三册-培养技能-·-单元-1-语法总结" tabindex="-1">第三册：培养技能 · 单元 1 语法总结 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-语法总结" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1 语法总结 {#第三册-培养技能-·-单元-1-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><h2 id="定语从句与证据限定" tabindex="-1">定语从句与证据限定 <a class="header-anchor" href="#定语从句与证据限定" aria-label="Permalink to &quot;定语从句与证据限定 {#定语从句与证据限定}&quot;">​</a></h2><p>限定性定语从句紧跟被修饰名词，帮助读者确定说的是哪一个人或物。指物可用 which 或 that，指人可用 who 或 that；关系词在从句中作宾语时通常可以省略，作主语时不能随意删掉。逗号隔开的非限定性从句用于补充信息，不能用 that，也不能省去关系词。描述目击报告时，还要把从句中的事实与主句中的推测区分开，不能因为用了复杂句就把不确定的信息写成结论。</p><p><strong>L1 原创例句：</strong> The tracks that we found near the gate may belong to a large dog.</p><p>我们在门附近发现的足迹可能是一只大狗留下的。</p><p><strong>易错：</strong> The tracks that appeared overnight 中 that 作主语，不能删；The tracks that we photographed 中 that 作宾语，可以删。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-001">Lesson 1</a></p><h2 id="过去进行时与突发事件" tabindex="-1">过去进行时与突发事件 <a class="header-anchor" href="#过去进行时与突发事件" aria-label="Permalink to &quot;过去进行时与突发事件 {#过去进行时与突发事件}&quot;">​</a></h2><p>过去进行时由 was 或 were 加动词 ing 构成，表示过去某一时刻正在展开的动作，常作为故事背景。一般过去时通常推进事件，说明一个动作发生或完成。when 后可以出现打断背景的短动作，while 常引出持续的背景，但二者并非机械地对应固定时态。know、believe 等状态动词通常不用进行时；如果叙述的是先后完成的动作，应直接使用一般过去时，不必为了显得生动而把每个动词都改为进行时。</p><p><strong>L2 原创例句：</strong> I was checking the clock when a loose screw fell onto the floor.</p><p>我正在检查钟表，突然一颗松动的螺丝掉到了地板上。</p><p><strong>易错：</strong> I was knowing the answer 不适合表达当时知道答案，应写 I knew the answer；进行时强调过程而非单纯过去时间。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-002">Lesson 2</a></p><h2 id="过去完成时的时间参照" tabindex="-1">过去完成时的时间参照 <a class="header-anchor" href="#过去完成时的时间参照" aria-label="Permalink to &quot;过去完成时的时间参照 {#过去完成时的时间参照}&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表达在另一个过去时间点之前已经发生的动作。它需要明确或可由上下文推知的过去参照点；单纯说明一个很久以前发生的事实，并不自动需要过去完成时。叙事中第一次交代较早事件时可用过去完成时，时间关系清楚后不必句句重复。before 和 after 已能表示先后时，一般过去时有时也自然，选择过去完成时主要是为了突出此前完成或对后续事件的影响。</p><p><strong>L3 原创例句：</strong> By the time the team reached the chamber, water had damaged several paintings.</p><p>团队到达墓室时，水已经损坏了几幅画。</p><p><strong>易错：</strong> Ancient builders had built it in 900 若没有另一个过去参照点，通常写 built 更直接；古老不等于过去完成。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-003">Lesson 3</a></p><h2 id="used-to-与过去习惯" tabindex="-1">used to 与过去习惯 <a class="header-anchor" href="#used-to-与过去习惯" aria-label="Permalink to &quot;used to 与过去习惯 {#used-to-与过去习惯}&quot;">​</a></h2><p>used to 后接动词原形，表示过去经常发生而现在通常不再发生的动作，也可描述过去状态。would 也能叙述过去反复动作，但通常需要先建立过去时间背景，且一般不直接替代 used to 描述静态事实。否定和疑问常写 didn&#39;t use to 与 Did ... use to。be used to 后接名词或动名词，表示习惯于某事，和 used to do 的意义、结构都不同；两者不能仅凭中文“习惯”互换。</p><p><strong>L4 原创例句：</strong> Leo used to hide his work clothes, but now he talks openly about his job.</p><p>利奥过去会藏起工作服，现在却坦然谈论自己的工作。</p><p><strong>易错：</strong> I am used to work early 应改为 I am used to working early；若说过去早上班，则是 I used to work early。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-004">Lesson 4</a></p><h2 id="间接疑问句的陈述语序" tabindex="-1">间接疑问句的陈述语序 <a class="header-anchor" href="#间接疑问句的陈述语序" aria-label="Permalink to &quot;间接疑问句的陈述语序 {#间接疑问句的陈述语序}&quot;">​</a></h2><p>转述问题时，疑问词之后通常使用主语加谓语的陈述语序，不能保留直接问句的倒装。一般疑问句用 whether 或 if 引出。主句用过去时，转述动词常向过去移动，但仍然有效的事实未必必须后移；时间地点和人称要依叙述视角调整。ask 后可以接人再接从句，不能把 ask 的宾语遗漏导致对象不清。报道数字时还应保留 about、at least 等限定，转述语法本身并不增加信息准确度。</p><p><strong>L5 原创例句：</strong> The editor asked how many households the survey had covered.</p><p>编辑问这项调查覆盖了多少户家庭。</p><p><strong>易错：</strong> The editor asked how many households had the survey covered 错在保留问句倒装，间接疑问从句要恢复陈述语序。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-005">Lesson 5</a></p><h2 id="一般过去时的被动语态" tabindex="-1">一般过去时的被动语态 <a class="header-anchor" href="#一般过去时的被动语态" aria-label="Permalink to &quot;一般过去时的被动语态 {#一般过去时的被动语态}&quot;">​</a></h2><p>被动结构由 be 的适当形式加过去分词组成，过去事件常用 was 或 were。原句宾语移到主语位置，动作实施者若未知、不重要或上下文已明，可不写 by 短语。只有能带宾语的及物用法通常能够这样转换，happen、arrive 等不能直接变为被动。被动不等于刻意隐藏责任；如责任人是报道重点，主动句更清楚。过去分词也可能作形容词，判断时需结合是否强调一个发生的动作。</p><p><strong>L6 原创例句：</strong> Two display cases were damaged before the alarm was raised.</p><p>警报发出前，两个展示柜遭到了损坏。</p><p><strong>易错：</strong> The accident was happened 不成立，因为 happen 不带直接宾语；应写 The accident happened。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-006">Lesson 6</a></p><h2 id="可数与不可数名词" tabindex="-1">可数与不可数名词 <a class="header-anchor" href="#可数与不可数名词" aria-label="Permalink to &quot;可数与不可数名词 {#可数与不可数名词}&quot;">​</a></h2><p>money 和 damage 在一般意义下通常不可数，不直接加 a，也不以普通复数表达若干份。note、coin、fragment 则可数，需要根据数量使用复数形式。表达不可数名词的单位可用 a sum of money 或 a piece of evidence，但单位词必须符合实际语境。a number of 加复数名词通常接复数谓语，the amount of 加不可数名词通常接单数谓语。damage 在法律赔偿意义下有 damages 的特殊用法，不能反推所有语境都可数。</p><p><strong>L7 原创例句：</strong> Several fragments were missing, but most of the printed number was still visible.</p><p>几块碎片不见了，但印刷号码的大部分仍清晰可见。</p><p><strong>易错：</strong> many money 应为 much money 或 a lot of money；many banknotes 则正确，因为 banknote 可数。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-007">Lesson 7</a></p><h2 id="地点介词与移动路径" tabindex="-1">地点介词与移动路径 <a class="header-anchor" href="#地点介词与移动路径" aria-label="Permalink to &quot;地点介词与移动路径 {#地点介词与移动路径}&quot;">​</a></h2><p>at 常把地点看作活动点，in 强调空间内部或较大区域，on 常表示接触表面；这些只是基本倾向，实际搭配还需考虑名词和语境。across 表示从一边到另一边，through 强调穿过内部，along 表示沿着路线。描述高度可用 above，描述紧邻上方并覆盖有时用 over，但二者并不总能互换。地点短语可以放句首建立场景，谓语仍须与真正的主语保持一致，不能被介词后的复数名词干扰。</p><p><strong>L8 原创例句：</strong> A narrow path runs through the forest and ends at the old gate.</p><p>一条狭窄小路穿过森林，终止于古老的大门。</p><p><strong>易错：</strong> across the forest 强调横穿整个林区，through the forest 强调在林中穿行；路线视角不同，不宜机械判为同义。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-008">Lesson 8</a></p><h2 id="比较级与比较对象一致" tabindex="-1">比较级与比较对象一致 <a class="header-anchor" href="#比较级与比较对象一致" aria-label="Permalink to &quot;比较级与比较对象一致 {#比较级与比较对象一致}&quot;">​</a></h2><p>比较级常由形容词加 er 或由 more 加多音节形容词构成，再用 than 引出比较对象。两边应比较同类事物，例如一只动物的速度与另一只动物的速度，而非速度与动物本身。much、far、slightly 可以修饰比较级，very 通常不能直接修饰比较级。the more ... the more ... 表示相关变化，不自动证明因果。使用一般现在时陈述倾向时，可加入 often、tend to 等词，避免把统计倾向说成没有例外的规律。</p><p><strong>L9 原创例句：</strong> The second ramp was slightly steeper than the first, so the cart moved faster.</p><p>第二个坡道比第一个略陡，因此小车移动得更快。</p><p><strong>易错：</strong> very faster 应改为 much faster 或 a little faster；very fast 则是原级搭配。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-009">Lesson 9</a></p><h2 id="过去反事实条件句" tabindex="-1">过去反事实条件句 <a class="header-anchor" href="#过去反事实条件句" aria-label="Permalink to &quot;过去反事实条件句 {#过去反事实条件句}&quot;">​</a></h2><p>典型结构为 if 加 had 加过去分词，主句用 would have 加过去分词，表示与已知过去事实相反的假设。主句也可用 might have 或 could have，分别突出可能性或能力条件，不能一律译成必然结果。if 从句通常不写 would have。反事实句只展示说话者设想的另一种结果，并不自动证明现实事件只有一个原因；讨论事故时尤其要区分可证实事实、合理推断和条件性评价。</p><p><strong>L10 原创例句：</strong> If the crew had received the warning earlier, they might have changed course.</p><p>如果船员更早收到警告，他们也许就会改变航向。</p><p><strong>易错：</strong> If they would have heard the alarm 不符合此处标准反事实条件结构，应写 If they had heard the alarm。</p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-010">Lesson 10</a></p>',65)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
